import {readFile} from 'node:fs/promises';
import sharp from 'sharp';
import {AuthoringStore} from '../../tooling/asset-studio/server/authoring/store';
import {resizeModelTextures} from '../../tooling/asset-studio/server/authoring/textureExport';
const work='.asset-work/ant-army-2026-10-11/nectarist',id='asset.models.units.ants-nectarist';
const store=new AuthoringStore(process.cwd());
try{await store.get(id)}catch{await store.dispatch({op:'asset.create',definition:{version:1,id,name:'Ant Nectarist',kind:'unit',revision:1,status:'draft',tags:['ants','nectarist','tripo','skinned'],resources:[],usesGeometry:false,transform:{scale:1,pivot:[0,0,0],up:'Y',forward:'+Z'},materials:[],bindings:{profile:'base',render:[],scenery:[]},capabilities:{},provenance:{method:'generated',licenseNote:'Original generated artwork for Under the Canopy.'}}});}
async function upload(role:string,format:string,bytes:Buffer,index=1){await store.dispatch({op:'asset.upload',id,expectedRevision:(await store.get(id)).revision,role,index,format,base64:bytes.toString('base64')});}
// Downsampling can carry ownership into adjacent orange chitin texels.
// Keep those mixed edge texels natural; fully red leaf texels retain the mask.
async function cleanOwnershipEdges(bytes:Buffer){
 const n=bytes.readUInt32LE(12),doc=JSON.parse(bytes.subarray(20,20+n).toString()),bin=bytes.subarray(28+n);
 const image=doc.images[doc.textures[doc.materials[0].pbrMetallicRoughness.baseColorTexture.index].source],view=doc.bufferViews[image.bufferView];
 const {data,info}=await sharp(bin.subarray(view.byteOffset??0,(view.byteOffset??0)+view.byteLength)).ensureAlpha().raw().toBuffer({resolveWithObject:true});
 for(let i=0;i<data.length;i+=4)if(data[i+1]>data[i+2]*1.25 && data[i]>data[i+1]*1.5)data[i+3]=0;
 const png=await sharp(data,{raw:{width:info.width,height:info.height,channels:4}}).png().toBuffer();
 const chunks:Buffer[]=[];let offset=0;
 for(const [i,v]of doc.bufferViews.entries()){
  const part=i===image.bufferView?png:bin.subarray(v.byteOffset??0,(v.byteOffset??0)+v.byteLength),pad=(4-offset%4)%4;
  chunks.push(Buffer.alloc(pad));offset+=pad;v.byteOffset=offset;v.byteLength=part.length;chunks.push(part);offset+=part.length;
 }
 doc.buffers[0].byteLength=offset;let binary=Buffer.concat(chunks),json=Buffer.from(JSON.stringify(doc));binary=Buffer.concat([binary,Buffer.alloc((4-binary.length%4)%4)]);json=Buffer.concat([json,Buffer.alloc((4-json.length%4)%4,32)]);
 const head=Buffer.alloc(20),bh=Buffer.alloc(8);head.writeUInt32LE(0x46546c67);head.writeUInt32LE(2,4);head.writeUInt32LE(28+json.length+binary.length,8);head.writeUInt32LE(json.length,12);head.writeUInt32LE(0x4e4f534a,16);bh.writeUInt32LE(binary.length);bh.writeUInt32LE(0x004e4942,4);return Buffer.concat([head,json,bh,binary]);
}
const glb=await cleanOwnershipEdges(await resizeModelTextures(await readFile(work+'/refinement.glb'),1024)),length=glb.readUInt32LE(12),doc=JSON.parse(glb.subarray(20,20+length).toString());
await upload('geometry','glb',glb);
await upload('source','blend',await readFile(work+'/source.blend'));
await upload('source','glb',await readFile(work+'/provider.glb'),2);
await upload('source','json',Buffer.from(JSON.stringify({filename:'publish-nectarist.ts',source:await readFile('.asset-work/ant-army-2026-10-11/publish-nectarist.ts','utf8')},null,2)),3);
await upload('reference','png',await readFile(work+'/reference.png'));
await upload('preview','png',await readFile(work+'/review-idle-0-front.png'));
await upload('preview','png',await readFile(work+'/review-idle-0-back.png'),2);
await upload('image','png',await sharp(work+'/review-idle-0-front.png').resize(128,128).png().toBuffer());
for(const [i,file] of ['adapt.py','refine.py','render-pose.py'].entries())await upload('recipe','py',await readFile(work+'/'+file),i+1);
const material=doc.materials[0],image=doc.images[doc.textures[material.pbrMetallicRoughness.baseColorTexture.index].source],view=doc.bufferViews[image.bufferView],start=28+length+(view.byteOffset??0),albedo=glb.subarray(start,start+view.byteLength);
await upload('albedo','png',albedo);await upload('team_mask','png',await sharp(albedo).extractChannel('alpha').png().toBuffer());
const stateClips:Record<string,string>={idle:'idle',walk:'walk',run:'run',cast:'cast',attack:'attack',hit:'hit',death:'death'};
await upload('generation','json',Buffer.from(JSON.stringify({provider:'Tripo Studio',task:'5b1b2b43-5eaf-4640-80a9-afe80b37096a',adaptation:JSON.parse(await readFile(work+'/adaptation.json','utf8')),refinement:'Broad leaf hood and robe ownership, rigid nectar jar and bowl; bowl-tip cast and adapted provider gaits',sourceFiles:{'adapt.py':'recipe.py','refine.py':'recipe_2.py','render-pose.py':'recipe_3.py','provider.glb':'source_2.glb','reference.png':'reference.png'},rebuild:'Materialize the named recipe files and provider in a staging nectarist directory; run Blender -b --python adapt.py -- <nectarist directory>.',runtimeTextureSize:1024},null,2)));
const a=await store.get(id);
await store.dispatch({op:'asset.save',expectedRevision:a.revision,definition:{...a,exportSettings:{textureSize:1024},bindings:{faction:'ants',profile:'base',render:[{id:'asset.ants.nectarist',geometry:{asset:id,role:'geometry',index:1},character:'base',projectile:'effect.weapon.nectar',projectileSocket:'socket_projectile',castContact:13/36,scale:2,healthHeight:2.15},{id:'icon.ants.nectarist',image:{asset:id,role:'image',index:1}}],scenery:[]},capabilities:{teamColor:{mode:'mask',slots:['TC_TeamColor'],mask:{role:'team_mask',index:1}},groundContact:{mode:'pivot'},animations:Object.entries(stateClips).map(([semantic,clip])=>({semantic,clip,loop:!['attack','cast','hit','death'].includes(semantic),events:semantic==='attack'?[{name:'release',time:13/24}]:[]})),sockets:[{name:'handL',node:'socket_handL',offset:[0,0,0]},{name:'handR',node:'socket_handR',offset:[0,0,0]},{name:'projectile',node:'socket_projectile',offset:[0,0,0]},{name:'cast',node:'socket_cast',offset:[0,0,0]}]}}});
console.log(await store.dispatch({op:'asset.validate',id}));
console.log(await store.dispatch({op:'asset.publish',id,expectedRevision:(await store.get(id)).revision}));
